Certainly! Below is an example of a Python script that implements a Contextual Multi-Armed Bandit (CMAB) using three different models. The script uses the `numpy` library for numerical operations and the `random` module for generating random numbers.

```python
import numpy as np
import random

class Model:
    def __init__(self):
        self.weights = None

    def update(self, context, action, reward):
        raise NotImplementedError("Subclasses must implement this method")

    def predict(self, context):
        raise NotImplementedError("Subclasses must implement this method")

class LinearModel(Model):
    def __init__(self, feature_dim):
        super().__init__()
        self.feature_dim = feature_dim
        self.weights = np.zeros(feature_dim)

    def update(self, context, action, reward):
        # Update weights based on the observed reward
        gradient = context * (reward - self.predict(context))
        self.weights += 0.1 * gradient

    def predict(self, context):
        return np.dot(context, self.weights)

class RandomModel(Model):
    def __init__(self):
        super().__init__()

    def update(self, context, action, reward):
        pass

    def predict(self, context):
        return random.uniform(0, 1)

class EpsilonGreedyBandit:
    def __init__(self, num_arms, epsilon=0.1):
        self.num_arms = num_arms
        self.epsilon = epsilon
        self.models = [LinearModel(2), RandomModel(), LinearModel(2)]
        self.best_model = None
        self.best_reward = float('-inf')

    def select_arm(self, context):
        if random.random() < self.epsilon:
            return random.randint(0, self.num_arms - 1)
        else:
            predictions = [model.predict(context) for model in self.models]
            return np.argmax(predictions)

    def update(self, context, arm, reward):
        self.models[arm].update(context, arm, reward)
        new_reward = self.models[arm].predict(context)
        if new_reward > self.best_reward:
            self.best_reward = new_reward
            self.best_model = self.models[arm]

# Example usage
if __name__ == "__main__":
    bandit = EpsilonGreedyBandit(num_arms=3, epsilon=0.1)
    contexts = [np.array([1, 2]), np.array([2, 3]), np.array([3, 4])]
    rewards = [0.8, 0.9, 0.7]

    for i in range(len(contexts)):
        context = contexts[i]
        arm = bandit.select_arm(context)
        reward = rewards[i]
        bandit.update(context, arm, reward)

        print(f"Context: {context}, Selected Arm: {arm}, Reward: {reward}")
```

### Explanation:
1. **Model Class**: This is an abstract base class with methods `update` and `predict`. Subclasses need to implement these methods.
2. **LinearModel**: A simple linear model where the prediction is the dot product of the context vector and the weight vector. The weights are updated using a gradient descent-like approach.
3. **RandomModel**: A model that always predicts a random value between 0 and 1.
4. **EpsilonGreedyBandit**: Implements the epsilon-greedy strategy for selecting arms. It maintains a list of models and updates them based on the observed rewards.
5. **Example Usage**: Demonstrates how to use the `EpsilonGreedyBandit` class with some sample contexts and rewards.

This script provides a basic framework for implementing a CMAB with multiple models. You can extend it by adding more sophisticated models or modifying the update rules.

