```csharp
using DocumentFormat.OpenXml.Packaging;
using DocumentFormat.OpenXml.Wordprocessing;

public void MergeWordDocuments(string sourceDoc1Path, string sourceDoc2Path, string destinationDocPath)
{
    // Open the first source document
    using (WordprocessingDocument sourceDoc1 = WordprocessingDocument.Open(sourceDoc1Path, false))
    {
        // Get the main document part
        MainDocumentPart mainPart1 = sourceDoc1.MainDocumentPart;

        // Create a new WordprocessingDocument for the merged document
        using (WordprocessingDocument mergedDoc = WordprocessingDocument.Create(destinationDocPath, WordprocessingDocumentType.Document))
        {
            // Add a new main document part
            MainDocumentPart mainPartMerged = mergedDoc.AddMainDocumentPart();

            // Copy the header, footer, and style definitions from the first document
            foreach (var section in mainPart1.Document.Body.Elements<SectionProperties>())
            {
                if (section.HeaderReference != null)
                {
                    var headerId = section.HeaderReference.Id.Value;
                    var headerPart = mainPart1.GetPartsOfType<HeaderPart>().FirstOrDefault(h => h.HeaderId == headerId);
                    if (headerPart != null)
                    {
                        var headerPartCopy = new HeaderPart();
                        headerPartCopy.FeedData(headerPart.GetStream());
                        mainPartMerged.AddPart(headerPartCopy);
                    }
                }

                if (section.FooterReference != null)
                {
                    var footerId = section.FooterReference.Id.Value;
                    var footerPart = mainPart1.GetPartsOfType<FooterPart>().FirstOrDefault(f => f.FooterId == footerId);
                    if (footerPart != null)
                    {
                        var footerPartCopy = new FooterPart();
                        footerPartCopy.FeedData(footerPart.GetStream());
                        mainPartMerged.AddPart(footerPartCopy);
                    }
                }

                // Copy the style definitions
                var styleDefinitionsPart = mainPart1.StyleDefinitionsPart;
                if (styleDefinitionsPart != null)
                {
                    var styleDefinitionsPartCopy = new StyleDefinitionsPart();
                    styleDefinitionsPartCopy.FeedData(styleDefinitionsPart.GetStream());
                    mainPartMerged.AddPart(styleDefinitionsPartCopy);
                }
            }

            // Copy the body content from the first document (first 2 pages)
            var bodyContent = mainPart1.Document.Body.Elements().ToList();
            int maxElementsToCopy = 2 * 30; // Assuming each page has around 30 elements
            var copiedBodyContent = bodyContent.Take(maxElementsToCopy).ToList();
            mainPartMerged.Document = new Document(new Body(copiedBodyContent));

            // Open the second source document
            using (WordprocessingDocument sourceDoc2 = WordprocessingDocument.Open(sourceDoc2Path, false))
            {
                // Get the main document part
                MainDocumentPart mainPart2 = sourceDoc2.MainDocumentPart;

                // Append the body content from the second document
                var remainingBodyContent = mainPart2.Document.Body.Elements().Skip(maxElementsToCopy).ToList();
                mainPartMerged.Document.Body.Append(remainingBodyContent);

                // Copy the glossary from the second document
                var glossary = mainPart2.Document.Body.Descendants<Glossary>().FirstOrDefault();
                if (glossary != null)
                {
                    mainPartMerged.Document.Body.Append(glossary);
                }
            }
        }
    }
}
```

This code assumes that both input documents have similar structures and that the first document contains at least two full pages. The `maxElementsToCopy` variable is used as a rough estimate for the number of elements per page, which may need adjustment based on your specific requirements.

Note that this implementation does not handle complex scenarios such as nested tables or lists, and it might require additional modifications depending on the exact structure of your input documents. Additionally, make sure to include the necessary references to the Open XML SDK libraries in your project before running this code.
