### Step 1: Implementing `FavoritesManager`

First, let's define the methods within the `FavoritesManager` class:

```php
<?php

namespace App\Favorites;

use App\Models\User;
use App\Models\Favorite;
use Illuminate\Support\Facades\Session;

class FavoritesManager
{
    public function addFavorite($userId, $businessName)
    {
        if ($userId) {
            // If there is a logged-in user, save the favorite to the database.
            return Favorite::updateOrCreate(
                ['user_id' => $userId, 'business_name' => $businessName],
                ['is_favorite' => true]
            );
        } else {
            // If no user is logged in, save the favorite to the session.
            $favorites = Session::get('favorites', []);
            $favorites[] = $businessName;
            Session::put('favorites', array_unique($favorites));
            return true;
        }
    }

    public function removeFavorite($userId, $businessName)
    {
        if ($userId) {
            // If there is a logged-in user, delete the favorite from the database.
            return Favorite::where('user_id', $userId)->where('business_name', $businessName)->delete();
        } else {
            // If no user is logged in, remove the favorite from the session.
            $favorites = Session::get('favorites', []);
            $favorites = array_diff($favorites, [$businessName]);
            Session::put('favorites', $favorites);
            return true;
        }
    }

    public function getFavorites($userId)
    {
        if ($userId) {
            // If there is a logged-in user, retrieve the favorites from the database.
            return Favorite::where('user_id', $userId)->pluck('business_name')->toArray();
        } else {
            // If no user is logged in, retrieve the favorites from the session.
            return Session::get('favorites', []);
        }
    }
}
