                return True

    # Check negatively sloped diagonals
    for c in range(COLS - 3):
        for r in range(3, ROWS):
            if board[r][c] == player and board[r-1][c+1] == player and board[r-2][c+2] == player and board[r-3][c+3] == player:
                return True

    return False

# Main game loop
current_player = 1
while True:
    print_board(board)
    col = int(input(f"Player {current_player}, choose a column (0-{COLS-1}): "))

    if not is_valid_move(board, col):
        print("Invalid move. Try again.")
        continue

    make_move(board, col, current_player)

    if check_winner(board, current_player):
        print_board(board)
        print(f"Player {current_player} wins!")
        break

    current_player = 3 - current_player  # Switch players (1 -> 2, 2 -> 1)

print("Game over.")
```

This code sets up a basic Connect-4 game where two players take turns placing their pieces on the board. The `print_board` function displays the current state of the board, `is_valid_move` checks if a given column is available for a new piece, `make_move` places a piece on the board, and `check_winner` determines if either player has won.

To run this script, you need to have Python installed along with the NumPy library (`pip install numpy`). You can then execute the script from your terminal or command prompt by running `python connect4.py`. Enjoy playing Connect-4!

